package com.example.fanlauncher
import android.app.*;import android.content.Intent;import android.content.pm.ServiceInfo;import android.graphics.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.widget.Toast;import androidx.core.app.NotificationCompat;import kotlinx.coroutines.*
class OverlayService:Service(){
 private lateinit var wm:WindowManager;private var edgeView:EdgeOverlayView?=null;private var fanView:FanLauncherView?=null;private val scope=CoroutineScope(Dispatchers.Main.immediate+SupervisorJob())
 companion object{@Volatile var isRunning=false;private set;var instance:OverlayService?=null;private set}
 override fun onCreate(){super.onCreate();instance=this;try{if(Build.VERSION.SDK_INT>=34)startForeground(1,buildNotification(),ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE)else startForeground(1,buildNotification());wm=getSystemService(WINDOW_SERVICE)as WindowManager;setupOverlay();isRunning=true}catch(t:Throwable){isRunning=false;runCatching{java.io.File(filesDir,"service_crash.log").writeText(t.stackTraceToString())};stopSelf()}}
 fun applySettings(){if(!isRunning)return;runOnMainThread{runCatching{edgeView?.let{wm.removeView(it)};edgeView=null;hideFan();setupOverlay()}}}
 private fun runOnMainThread(block:()->Unit){if(Looper.myLooper()==Looper.getMainLooper())block()else Handler(Looper.getMainLooper()).post(block)}
 private fun setupOverlay(){val s=FanSettings.load(this);val d=resources.displayMetrics.density;val p=WindowManager.LayoutParams((s.edgeWidthDp*d).toInt(),-1,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL or WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT).apply{gravity=if(s.edge==EdgeSide.RIGHT)Gravity.END or Gravity.CENTER_VERTICAL else Gravity.START or Gravity.CENTER_VERTICAL};val e=EdgeOverlayView(this,s);e.onSwipeStart={x,y->showFan(x,y)};e.onSwipeMove={x,y->fanView?.updateSelection(x,y)};e.onSwipeEnd={fanView?.commitSelection();hideFan()};wm.addView(e,p);edgeView=e}
 private fun showFan(x:Float,y:Float){if(fanView!=null)return;val s=FanSettings.load(this);val p=WindowManager.LayoutParams(-1,-1,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE or WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT).apply{gravity=Gravity.TOP or Gravity.START};val f=FanLauncherView(this,s);f.onItemSelected={executeAction(it)};wm.addView(f,p);fanView=f;scope.launch{f.tier1Items=buildItems(s.tier1Apps,s.tier1Count,s.showScreenshot,s.showTranslate);f.tier2Items=if(s.tiers==2)buildItems(s.tier2Apps,s.tier2Count,false,false)else emptyList();f.setVertexY(y);f.updateSelection(x,y)}}
 private suspend fun buildItems(pkgs:List<String>,maxApps:Int,ss:Boolean,tr:Boolean):List<FanItem> = withContext(Dispatchers.Default){val pm=packageManager;val r=pkgs.take(maxApps).mapNotNull{pkg->runCatching{val i=pm.getApplicationInfo(pkg,0);FanItem(pm.getApplicationLabel(i).toString(),pm.getApplicationIcon(i),AppColorExtractor.extract(this@OverlayService,pkg),FanAction.LaunchApp(pkg))}.getOrNull()}.toMutableList();if(ss)r+=FanItem("Screenshot",null,0xFF455A64.toInt(),FanAction.Screenshot);if(tr)r+=FanItem("Translate",null,0xFF00897B.toInt(),FanAction.Translate);r}
 private fun hideFan(){fanView?.let{runCatching{wm.removeView(it)}};fanView=null}
 private fun executeAction(item:FanItem){when(val a=item.action){is FanAction.LaunchApp->packageManager.getLaunchIntentForPackage(a.packageName)?.also{it.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(it)};FanAction.Screenshot->ScreenshotAccessibilityService.instance?.capture{b->if(b!=null)saveScreenshot(b)else Toast.makeText(this,"スクリーンショットに失敗しました",Toast.LENGTH_SHORT).show()};FanAction.Translate->ScreenshotAccessibilityService.instance?.capture{b->b?.let{scope.launch{ScreenTranslator.translateAndOverlay(this@OverlayService,it,wm)}}}}}
 private fun saveScreenshot(b:Bitmap){scope.launch(Dispatchers.IO){val v=android.content.ContentValues().apply{put(MediaStore.Images.Media.DISPLAY_NAME,"fanlauncher_"+System.currentTimeMillis()+".png");put(MediaStore.Images.Media.MIME_TYPE,"image/png");if(Build.VERSION.SDK_INT>=29){put(MediaStore.Images.Media.RELATIVE_PATH,Environment.DIRECTORY_PICTURES+"/FanLauncher");put(MediaStore.Images.Media.IS_PENDING,1)}};val u=contentResolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);if(u==null)return@launch;val ok=runCatching{contentResolver.openOutputStream(u)?.use{b.compress(Bitmap.CompressFormat.PNG,100,it)}?:false}.getOrDefault(false);if(Build.VERSION.SDK_INT>=29)contentResolver.update(u,android.content.ContentValues().apply{put(MediaStore.Images.Media.IS_PENDING,0)},null,null);if(!ok)contentResolver.delete(u,null,null)}}
 private fun buildNotification():Notification{val c=NotificationChannel("fan","FanLauncher",NotificationManager.IMPORTANCE_LOW);(getSystemService(NOTIFICATION_SERVICE)as NotificationManager).createNotificationChannel(c);return NotificationCompat.Builder(this,"fan").setContentTitle("FanLauncher 稼働中").setContentText("エッジからスワイプでランチャーを開きます").setSmallIcon(android.R.drawable.ic_menu_compass).setOngoing(true).build()}
 override fun onStartCommand(i:Intent?,flags:Int,startId:Int)=START_STICKY
 override fun onDestroy(){isRunning=false;instance=null;edgeView?.let{runCatching{wm.removeView(it)}};hideFan();scope.cancel();super.onDestroy()}
 override fun onBind(i:Intent?):IBinder?=null
}